"""Optional separate check of the deterministic first-moment peak against the typical peak."""
from fractions import Fraction as F
from itertools import product
from math import comb, factorial
import independent as core

def verify_bedrosian():
    # All labeled Cayley trees for size up to seven, generated by contracting Prüfer codes.
    for n in range(2,8):
        tot=[0]*(n+1); counts=0
        for seq in product(range(n),repeat=n-2):
            d=[seq.count(i)+1 for i in range(n)];es=[]
            for old in seq:
                leaf=d.index(1);es.append((1<<old)|(1<<leaf))
                d[old]-=1;d[leaf]-=1
            es.append(sum(1<<i for i in range(n) if d[i]))
            for mask in range(1<<n):
                if all(mask&e!=e for e in es):tot[mask.bit_count()]+=1
            counts+=1
        core.require(counts==n**(n-2) and tot[0]==counts and not tot[n])
        for k in range(1,n):
            core.require(F(tot[k],counts)==comb(n,k)*F(n-k,n)**(k-1))
    print('Bedrosian expectations verified by exhaustive Prüfer enumeration, n=2..7')

def gap():
    # Different slope test: exponentiate the rational x/(1-x), using an UPPER bound:
    # tail beyond sixth degree <= (r^7/7!) / (1-r/8).
    x=F(3074,10000); y=(1-x)**2/x; r=x/(1-x)
    upper=sum((r**k/factorial(k) for k in range(7)),F(0))+r**7/factorial(7)/(1-r/8)
    core.require(0<r<1 and upper<y)
    print('Strict exp comparison y-upper =',y-upper)
    core.K=960; core.D=11; core.HEIGHT=14
    # Same independent CDF procedure, increasing spatial resolution; no author code.
    lower,upper=core.point(0),core.point(core.K)
    las,uas=lower,upper
    for h in range(core.HEIGHT):
        lower,upper=core.mix_product(upper,True),core.mix_product(lower,False)
        las,uas=core.cdf_div(lower,uas,True),core.cdf_div(upper,las,False)
    a,b=core.occupation(las),core.occupation(uas)
    core.require(F(305300,10**6)<=a<=b<=F(306955,10**6))
    sc=10**6
    print('Independent K=960 fine bounds (millionths):',int(a*sc),-(-b*sc//1))
    core.require(x-b>F(445,10**6))
    print('Asymptotic first-moment/typical peak gap greater than 445 millionths: PASS')
if __name__=='__main__':
    verify_bedrosian()
    gap()
